export const GENRE_BY_ID: Readonly<Record<string, GenreInfo>> = Object.fromEntries(GENRES.map((g) => [g.id, g]));

export function genreLabel(id: string): string {
  const g = GENRE_BY_ID[id];
  return g?.short ?? g?.label ?? id.replace(/-/g, ' ');
}

/** A game's pill: its genre, and for a freeform game the genre it builds on once its design says so. */
export function gameGenreLabel(genre: string, design: unknown): string {
  const base = (design as { gdd?: { base?: unknown } } | null)?.gdd?.base;
  return genre === 'freeform' && typeof base === 'string' ? `Freeform · ${GENRE_BY_ID[base]?.label ?? base}` : genreLabel(genre);
}

/** A version's own controls legend (design.controls, written by the publisher from the game's systems), or null. */
export function controlsOf(design: unknown): Array<[string, string]> | null {
  const c = (design as { controls?: unknown } | null)?.controls;
  if (!Array.isArray(c) || c.length === 0) return null;
  return c.every((row) => Array.isArray(row) && row.length === 2 && typeof row[0] === 'string' && typeof row[1] === 'string') ? (c as Array<[string, string]>) : null;
}
